<script setup lang="ts">
import {ref,watch,nextTick,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAccount} from './store'
import {api,statusName} from './api'
import {readEvents} from './stream.mjs'
import ShopCard from './ShopCard.vue'
import RichText from './RichText.vue'
import ActionDialog from './ActionDialog.vue'
import DemoGuide from './DemoGuide.vue'
import {demoChat,resetDemo} from './demo.mjs'
const isDemo=import.meta.env.MODE==='demo'
const route=useRoute(),router=useRouter(),account=useAccount()
const messages=ref<any[]>([]),input=ref(''),busy=ref(false),error=ref(''),session=ref<string|null>(null),context=ref<string|null>(null),draft=ref<any>(null),trace=ref<any>(null),list=ref<HTMLElement>(),tasks=ref<any[]>([])
let controller:AbortController|null=null,requestId:string|null=null,revision=0
async function stop(){for(const m of messages.value)if(m.pending){m.pending=false;m.text='已停止生成，可继续提问。'};messages.value=[...messages.value];revision++;controller?.abort();controller=null;if(requestId){const id=requestId;requestId=null;try{await api(`/api/requests/${id}`,'DELETE')}catch{}}busy.value=false}
async function scroll(){await nextTick();if(list.value)list.value.scrollTop=list.value.scrollHeight}
async function load(){await stop();const rev=revision;error.value='';messages.value=[];draft.value=null;context.value=null;session.value=String(route.params.id||'')||null;if(session.value){try{const data=await api(`/api/sessions/${session.value}/messages`);if(rev!==revision)return;messages.value=data.messages;context.value=data.last_task_response?.recommendation_run_id||data.last_task_response?.run_id||data.last_response?.recommendation_run_id||data.last_response?.run_id||null;await scroll()}catch(e){error.value=(e as Error).message}}}
watch(()=>route.params.id,()=>{if((route.params.id||null)!==session.value)load()},{immediate:true})
async function send(text?:string){const message=text||input.value.trim();if(!message||busy.value)return;error.value='';input.value='';busy.value=true;const rev=++revision;requestId=crypto.randomUUID();controller=new AbortController();messages.value.push({id:crypto.randomUUID(),role:'user',text:message});const reply:any={id:crypto.randomUUID(),role:'assistant',text:'正在理解你的需求…',pending:true};messages.value.push(reply);await scroll();let result:any
try{if(isDemo){await new Promise(resolve=>setTimeout(resolve,450));result=await demoChat({message,session_id:session.value},controller.signal)}else{const response=await fetch('/api/chat/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,session_id:session.value,context_run_id:context.value,request_id:requestId}),signal:controller.signal});if(!response.ok){if(response.status===401)account.clear();throw new Error((await response.json()).detail||'请求失败')}result=await readEvents(response,item=>{if(rev!==revision)return;if(item.type==='event'&&item.data.event==='session_started')session.value=item.data.session_id;if(item.type==='event'&&item.data.event==='tool_start'){reply.text='正在执行业务查询与校验…';messages.value=[...messages.value]}});}if(rev!==revision)return;reply.text=result.answer;reply.result=result;reply.run_id=result.run_id;reply.pending=false;messages.value=[...messages.value];session.value=result.session_id||session.value;context.value=result.recommendation_run_id||(result.shops?.length?result.run_id:context.value);if(result.action_draft)draft.value=result.action_draft;if(session.value)await router.replace('/chat/'+session.value);await account.refreshSessions();await scroll()}catch(e){if(rev===revision){reply.pending=false;reply.text=(e as Error).name==='AbortError'?'已停止生成':(e as Error).message;messages.value=[...messages.value]}}finally{if(rev===revision){busy.value=false;requestId=null;controller=null}}}
async function buy(shop:any,coupon:any,result:any){if(busy.value)return;try{draft.value=await api('/api/actions/vouchers/prepare','POST',{run_id:result.recommendation_run_id||result.run_id,shop_id:shop.id,voucher_id:coupon.id})}catch(e){error.value=(e as Error).message}}
async function showTrace(id:string){try{trace.value=await api(`/api/runs/${id}`)}catch(e){error.value=(e as Error).message}}
async function showTasks(){try{tasks.value=(await api('/api/tasks')).tasks;if(!tasks.value.length)error.value='暂无可恢复任务'}catch(e){error.value=(e as Error).message}}
async function resume(id:string){try{const result=await api(`/api/tasks/${id}/resume`,'POST');session.value=result.session_id;messages.value.push({id:crypto.randomUUID(),role:'assistant',text:result.answer,result});await router.replace('/chat/'+result.session_id);await account.refreshSessions()}catch(e){error.value=(e as Error).message}}
async function prepareDemo(){
  try{draft.value=await api('/api/catalog/prepare','POST',{shop_id:101,voucher_id:9001})}catch(e){error.value=(e as Error).message}
}
async function restartDemo(){await stop();resetDemo();await router.replace('/chat');await load();await account.refreshSessions()}
function newChat(){load()}
onMounted(()=>{window.addEventListener('new-chat',newChat);const message=sessionStorage.getItem('citylens-handoff');if(message){sessionStorage.removeItem('citylens-handoff');input.value=message}})
onUnmounted(()=>{stop();window.removeEventListener('new-chat',newChat)})
</script>
<template><div class="chat-layout"><DemoGuide v-if="isDemo" :busy="busy" @next="send" @prepare="prepareDemo" @reset="restartDemo"/><div class="chat-toolbar"><span class="muted small">{{session?'正在继续同一会话':'开启一个新计划'}}</span><button v-if="!isDemo" class="outline" @click="showTasks">可恢复任务</button><button class="outline" :disabled="!messages.some(m=>m.run_id)" @click="showTrace([...messages].reverse().find(m=>m.run_id).run_id)">运行记录 ↗</button></div><div class="error" v-if="error" role="alert">{{error}}</div><div class="transcript" ref="list"><div v-if="isDemo&&!messages.length" class="demo-placeholder"><span class="eyebrow">你的城市生活，从一个需求开始</span><h3>“两个人，先吃火锅再唱歌，400元够吗？”</h3><p>让条件变成计划，再把计划变成一个可确认的动作。</p><div><span>多轮条件保留</span><span>预算校验</span><span>确认后提交</span></div></div><div class="welcome" v-if="!messages.length&&!isDemo"><div class="eyebrow">YOUR CITY, YOUR WAY</div><h2>下一站，想去哪里？</h2><p>找一家好店，看看大家的体验，安排你的城市生活。</p><div class="suggestions"><button @click="input='帮我找火锅店，人均150以内'">找一家火锅店</button><button @click="input='我想订个KTV'">安排朋友聚会</button><button @click="input='查一下我的订单'">查看我的订单</button></div></div><article v-for="m in messages" :key="m.id" :class="['message',m.role]"><div class="speaker">{{m.role==='user'?'你':'CityLens'}}</div><div class="message-body"><RichText :text="m.text"/><template v-if="m.result"><div class="conditions"><span v-for="c in m.result.confirmed_constraints" :key="c" class="pill">{{c}}</span></div><div class="shop-grid"><ShopCard v-for="s in m.result.shops" :key="s.id" :shop="s" @detail="router.push('/shops/'+s.id)" @buy="buy(s,$event,m.result)"/></div><div class="itinerary" v-for="(it,i) in m.result.itineraries" :key="i"><h3>方案 {{i+1}} · 预计总计 ¥{{it.estimated_total}}</h3><p class="small">{{it.reason}}</p><div class="shop-grid"><ShopCard v-for="s in it.stops" :key="s.id" :shop="s" @detail="router.push('/shops/'+s.id)" @buy="buy(s,$event,m.result)"/></div></div><div v-for="c in m.result.business_choices" :key="c.index" class="choice"><span>{{c.index}}. {{c.shop_name}} · {{c.title}}</span><button class="outline" :disabled="busy" @click="send('第'+c.index+'张')">选择这张</button></div><div v-for="o in m.result.personal_orders" :key="o.order_id||o.orderId" class="choice"><span>{{o.voucher_title||o.voucherTitle}} · {{statusName(o.status)}}</span><button class="text-button" @click="router.push('/orders')">查看订单</button></div><div class="suggestions"><button v-for="r in m.result.relaxations" :key="r.label" :disabled="busy" @click="send(r.message)">{{r.label}}</button></div><details v-if="m.result.candidate_decisions?.length"><summary>筛选与排序依据</summary><p v-for="c in m.result.candidate_decisions" :key="c.shop_id" class="small">{{c.name}}：{{c.reasons.join('；')}}</p></details><button v-if="m.run_id" class="text-button small" @click="showTrace(m.run_id)">本轮运行记录 ↗</button></template></div></article></div><form class="composer" @submit.prevent="send()"><textarea v-model="input" maxlength="500" rows="2" :disabled="busy" aria-label="消息" :placeholder="isDemo?'可输入案例原句，或点击上方按钮逐步体验…':'继续聊聊，或者告诉我你的新计划…'" @keydown.enter.exact.prevent="send()"/><div class="row"><span class="muted small">{{isDemo?'已验证案例回放 · 当前不连接实时模型':'城市生活助手 · 按需调用点评工具'}}</span><button v-if="busy" type="button" class="outline" @click="stop">停止</button><button v-else class="primary" :disabled="!input.trim()">发送 ↑</button></div></form><div class="footnote">{{isDemo?'模拟交易 · 数据仅在当前页面内存中 · 刷新即重置':'下单和领券需明确确认 · 支付为本地模拟 · Shift+Enter 换行'}}</div></div><ActionDialog v-if="draft" :key="draft.action_id" :draft="draft" @close="draft=null"/><div class="overlay" v-if="trace"><section class="modal wide trace-modal" role="dialog" aria-modal="true" aria-labelledby="trace-title"><div class="trace-header"><button class="close" aria-label="关闭" @click="trace=null">×</button><h2 id="trace-title">Agent 运行记录</h2><p class="muted small">{{trace.run_id}} · {{trace.status}} · {{trace.mode}}</p></div><div class="trace-body"><ol class="trace"><li v-for="(e,i) in trace.events" :key="i"><b>{{e.event}}</b><span>{{e.elapsed_ms}} ms</span><pre>{{JSON.stringify(e,null,2)}}</pre></li></ol></div></section></div><div class="overlay" v-if="tasks.length"><section class="modal" role="dialog" aria-modal="true"><button class="close" @click="tasks=[]">×</button><h2>可恢复任务</h2><div v-for="t in tasks" :key="t.run_id" class="choice"><span>{{t.run_id}} · {{t.status}}</span><button class="outline" @click="resume(t.run_id);tasks=[]">恢复</button></div></section></div></template>
